/* index.html UI (defer): components, then the easter eggs.
 * GENERATED by scripts/build.mjs — edit the sources, then run `npm run build`. */

(() => {
  'use strict';

  const { config, dom, storage, i18n, bus } = window.CNTU;
  const { $, $$ } = dom;
  const { STORAGE_KEYS } = config;
  const local = storage.local;

  const LANG_CODES = { uk: 'UA', en: 'EN', pl: 'PL', de: 'DE', es: 'ES', ja: 'JA' };

  const initLanguage = () => {
    const menu = $('#langMenu');
    const button = $('#langMenuButton');
    const list = $('#langMenuList');
    const items = $$('.lang-menu__item', list ?? document);

    const render = (lang) => {
      if (!menu) return;
      $('.lang-menu__code', button).textContent = LANG_CODES[lang] ?? lang.toUpperCase();
      const current = $('.lang-menu__current', button);
      current.textContent = i18n.names[lang];
      current.lang = lang;
      items.forEach((item) =>
        item.setAttribute('aria-checked', String(item.dataset.lang === lang)),
      );
    };
    i18n.onChange(render);

    const set = (lang) => {
      const next = i18n.supported(lang) ?? i18n.defaultLang;
      local.set(STORAGE_KEYS.lang, next); // only an explicit choice is saved
      return i18n.apply(next);
    };

    i18n.apply(i18n.initial); // picked by core/i18n.js (saved value or browser languages)
    window.addEventListener('storage', (event) => {
      if (event.key === STORAGE_KEYS.lang) i18n.apply(event.newValue ?? i18n.initial);
    });

    if (!menu || !button || !list) return { set };
    menu.hidden = false;
    render(i18n.lang);

    const isOpen = () => button.getAttribute('aria-expanded') === 'true';
    let outside = null;

    const close = ({ focusButton = false } = {}) => {
      if (!isOpen()) return;
      button.setAttribute('aria-expanded', 'false');
      list.hidden = true;
      outside?.abort();
      outside = null;
      if (focusButton) button.focus();
    };

    const open = (focus = 'checked') => {
      button.setAttribute('aria-expanded', 'true');
      list.hidden = false;
      const checked = items.findIndex((item) => item.getAttribute('aria-checked') === 'true');
      const index =
        focus === 'last' ? items.length - 1 : focus === 'first' ? 0 : Math.max(0, checked);
      items[index].focus();
      outside = new AbortController();
      document.addEventListener(
        'pointerdown',
        (event) => {
          if (!menu.contains(event.target)) close();
        },
        { signal: outside.signal },
      );
      menu.addEventListener(
        'focusout',
        (event) => {
          if (!menu.contains(event.relatedTarget)) close();
        },
        { signal: outside.signal },
      );
    };

    button.addEventListener('click', () => (isOpen() ? close() : open()));
    button.addEventListener('keydown', (event) => {
      if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
        event.preventDefault();
        open(event.key === 'ArrowUp' ? 'last' : 'checked');
      }
    });

    list.addEventListener('keydown', (event) => {
      const index = items.indexOf(document.activeElement);
      const move = { ArrowDown: index + 1, ArrowUp: index - 1, Home: 0, End: items.length - 1 };
      if (event.key in move) {
        event.preventDefault();
        items[(move[event.key] + items.length) % items.length].focus();
      } else if (event.key === 'Escape') {
        event.preventDefault();
        close({ focusButton: true });
      } else if (event.key === 'Tab') {
        close();
      }
    });

    items.forEach((item) => {
      item.addEventListener('click', () => {
        close({ focusButton: true });
        set(item.dataset.lang);
      });
    });

    return { set };
  };

  const language = initLanguage();
  bus.on('lang', (event) => language.set(event.detail?.lang));
})();

(() => {
  'use strict';

  const { config, theme, bus } = window.CNTU;
  const { STORAGE_KEYS } = config;

  const initThemeToggle = () => {
    const toggle = document.getElementById('themeToggle');

    theme.render(theme.isDark()); // sync ARIA/meta with what core/theme.js applied

    theme.systemDark?.addEventListener('change', (event) => {
      if (!theme.saved()) theme.render(event.matches);
    });

    window.addEventListener('storage', (event) => {
      if (event.key === STORAGE_KEYS.theme) theme.render(theme.resolve(event.newValue));
    });

    bus.on('theme', (event) => theme.set(event.detail?.theme === 'dark'));

    if (!toggle) return;
    toggle.hidden = false;
    toggle.addEventListener('click', () => theme.set(!theme.isDark()));
  };

  initThemeToggle();
})();

(() => {
  'use strict';

  const { config, dom, i18n } = window.CNTU;
  const { $ } = dom;
  const mobileQuery = window.matchMedia(config.MOBILE_MEDIA);

  const initMenu = () => {
    const burger = $('#burger');
    const nav = $('#primary-nav');
    if (!burger || !nav) return;

    const label = $('.visually-hidden', burger);
    let openController = null; // AbortController for listeners bound while open

    const isOpen = () => burger.getAttribute('aria-expanded') === 'true';
    const renderLabel = () => {
      const text = i18n.t(isOpen() ? 'menu.close' : 'menu.open');
      if (text) label.textContent = text; // dictionary may still be loading
    };

    const close = ({ returnFocus = false } = {}) => {
      const focusWasInside = nav.contains(document.activeElement);
      burger.setAttribute('aria-expanded', 'false');
      nav.classList.remove('is-open');
      nav.inert = mobileQuery.matches; // closed menu: unreachable by Tab and AT
      openController?.abort();
      openController = null;
      renderLabel();
      if (returnFocus || (focusWasInside && mobileQuery.matches)) burger.focus();
    };

    const open = () => {
      burger.setAttribute('aria-expanded', 'true');
      nav.classList.add('is-open');
      nav.inert = false;
      renderLabel();

      openController = new AbortController();
      const { signal } = openController;

      document.addEventListener(
        'keydown',
        (event) => {
          if (event.key === 'Escape' && !document.querySelector('dialog[open]')) {
            close({ returnFocus: true });
          }
        },
        { signal },
      );
      document.addEventListener(
        'click',
        (event) => {
          if (!nav.contains(event.target) && !burger.contains(event.target)) close();
        },
        { signal },
      );
      nav.addEventListener(
        'focusout',
        (event) => {
          const next = event.relatedTarget;
          if (next && !nav.contains(next) && next !== burger) close();
        },
        { signal },
      );

      $('a', nav)?.focus();
    };

    burger.hidden = false;
    burger.addEventListener('click', () => (isOpen() ? close({ returnFocus: true }) : open()));
    nav.addEventListener('click', (event) => {
      if (isOpen() && event.target.closest('a')) close();
    });
    mobileQuery.addEventListener('change', () => close());
    i18n.onChange(renderLabel);

    close();
  };

  initMenu();
})();

(() => {
  'use strict';

  const { $ } = window.CNTU.dom;

  const initHeaderOffset = () => {
    const header = $('.header');
    if (!header || !('ResizeObserver' in window)) return;
    new ResizeObserver(([entry]) => {
      const height = Math.round(entry.borderBoxSize?.[0]?.blockSize ?? entry.contentRect.height);
      document.documentElement.style.setProperty('--header-h', `${height}px`);
    }).observe(header);
  };

  initHeaderOffset();
})();

(() => {
  'use strict';

  const { $$ } = window.CNTU.dom;

  const initNavHighlight = () => {
    if (!('IntersectionObserver' in window)) return;

    const pairs = $$('.nav__link[href^="#"]')
      .map((link) => ({ link, section: document.getElementById(link.hash.slice(1)) }))
      .filter(({ section }) => section);
    if (!pairs.length) return;

    const visible = new Set();

    const render = () => {
      const active = pairs.filter(({ section }) => visible.has(section)).at(-1);
      pairs.forEach(({ link }) => {
        if (link === active?.link) link.setAttribute('aria-current', 'location');
        else link.removeAttribute('aria-current');
      });
    };

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach(({ target, isIntersecting }) => {
          if (isIntersecting) visible.add(target);
          else visible.delete(target);
        });
        render();
      },
      { rootMargin: '-40% 0px -55% 0px' },
    );

    pairs.forEach(({ section }) => observer.observe(section));
  };

  initNavHighlight();
})();

