(() => {
  'use strict';

  const { dom, storage, i18n, bus } = window.CNTU;
  const { $, $$ } = dom;

  const MATRIX = {
    clicks: 7,
    windowMs: 3000,
    hintAt: 4,
    rainMs: 6500,
    typeMs: 35,
    answers: [
      ...['матриця', 'матрицю', 'матриці', 'матрицею', 'матрица', 'матрицу'], // uk (+ru)
      ...['matrix', 'the matrix', 'a matrix', 'matrices'], // en
      ...['macierz', 'macierzą', 'macierzy', 'macierze', 'matrix', 'matriks', 'matryca'], // pl
      ...['matrix', 'die matrix', 'eine matrix', 'matrizen', 'matrixen'], // de
      ...['matriz', 'la matriz', 'una matriz', 'matrices', 'matrix'], // es
      ...['行列', 'マトリックス', 'マトリクス', 'ぎょうれつ', 'まとりっくす'], // ja
    ],
    glyphs:
      'アイウエオカキクケコサシスセソタチツテトナニヌネノハヒフヘホマミムメモヤユヨラリルレロワヲン' +
      '0123456789' +
      'АБВГҐДЕЄЖЗИІЇЙКЛМНОПРСТУФХЦЧШЩЬЮЯ',
  };

  const RAIN_FONT =
    '"Noto Sans Mono CJK JP", "MS Gothic", "Osaka-Mono", "Hiragino Kaku Gothic ProN", ' +
    '"Noto Sans CJK JP", "Yu Gothic", ui-monospace, monospace';

  const normalizeAnswer = (value) =>
    value
      .toLowerCase()
      .replace(/[^\p{L}\p{N} ]/gu, '')
      .replace(/\s+/g, ' ')
      .trim();

  const initMatrixEgg = () => {
    const logo = $('.logo');
    if (!logo) return null;

    const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
    const root = document.documentElement;
    let clickTimes = [];
    let session = null; // { controller, canvas, dialog, rafId, ... } while active

    const startRain = (onDone) => {
      const canvas = document.createElement('canvas');
      canvas.className = 'matrix-rain';
      canvas.setAttribute('aria-hidden', 'true');
      document.body.append(canvas);
      const ctx = canvas.getContext('2d');

      const state = { columns: [], fontSize: 16, dpr: 1, elapsed: 0, last: 0, rafId: 0 };
      const message = [...i18n.t('matrix.hidden')];

      const resize = () => {
        state.dpr = Math.min(window.devicePixelRatio || 1, 3);
        canvas.width = Math.floor(window.innerWidth * state.dpr);
        canvas.height = Math.floor(window.innerHeight * state.dpr);
        state.fontSize = Math.round(16 * state.dpr);
        const count = Math.ceil(canvas.width / state.fontSize);
        state.columns = Array.from({ length: count }, (_, i) => ({
          y: state.columns[i]?.y ?? Math.random() * -50,
          messageIndex: -1, // ≥ 0 while this column spells the hidden hint
        }));
        ctx.fillStyle = '#000';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
      };

      const randomGlyph = () => MATRIX.glyphs[Math.floor(Math.random() * MATRIX.glyphs.length)];

      const frame = (now) => {
        const delta = state.last ? Math.min(now - state.last, 100) : 16;
        state.last = now;
        state.elapsed += delta;

        ctx.fillStyle = 'rgb(0 0 0 / 8%)';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.font = `${state.fontSize}px ${RAIN_FONT}`;

        if (Math.random() < 0.02) {
          const column = state.columns[Math.floor(Math.random() * state.columns.length)];
          if (column && column.messageIndex < 0) {
            column.messageIndex = 0;
            column.y = 0;
          }
        }

        state.columns.forEach((column, i) => {
          const spelling = column.messageIndex >= 0;
          const glyph = spelling ? message[column.messageIndex] : randomGlyph();
          ctx.fillStyle = spelling ? '#eafff0' : '#00ff41';
          ctx.shadowBlur = spelling ? 12 * state.dpr : 0;
          ctx.shadowColor = '#00ff41';
          ctx.fillText(glyph, i * state.fontSize, column.y * state.fontSize);

          if (spelling) {
            column.messageIndex += 1;
            if (column.messageIndex >= message.length) column.messageIndex = -1;
          }
          column.y += 1;
          if (column.y * state.fontSize > canvas.height && Math.random() > 0.975) column.y = 0;
        });
        ctx.shadowBlur = 0;

        if (state.elapsed >= MATRIX.rainMs) {
          onDone();
          return;
        }
        state.rafId = window.requestAnimationFrame(frame);
      };

      const pause = () => {
        window.cancelAnimationFrame(state.rafId);
        state.rafId = 0;
        state.last = 0;
      };
      const resume = () => {
        if (!state.rafId) state.rafId = window.requestAnimationFrame(frame);
      };

      const { signal } = session.controller;
      window.addEventListener('resize', resize, { signal });
      document.addEventListener('visibilitychange', () => (document.hidden ? pause() : resume()), {
        signal,
      });

      document.addEventListener(
        'keydown',
        (event) => {
          if (event.key === 'Escape' && !session?.dialog) exit();
        },
        { signal },
      );

      resize();
      resume();
      session.canvas = canvas;
      session.stopRain = pause;
    };

    const typeLines = (target, lines, done) => {
      if (reducedMotion.matches) {
        target.textContent = lines.join('\n');
        done();
        return;
      }
      const text = lines.join('\n');
      let index = 0;
      const tick = () => {
        index += 1;
        target.textContent = text.slice(0, index);
        if (index < text.length) session.typeTimer = window.setTimeout(tick, MATRIX.typeMs);
        else done();
      };
      tick();
    };

    const openDialog = () => {
      const dialog = document.createElement('dialog');
      dialog.className = 'matrix-dialog';
      dialog.setAttribute('aria-modal', 'true');
      dialog.setAttribute('aria-labelledby', 'matrix-title');
      dialog.setAttribute('aria-describedby', 'matrix-riddle');
      dialog.innerHTML = `
        <h2 class="matrix-dialog__title" id="matrix-title" data-i18n="matrix.dialogLabel"></h2>
        <p class="visually-hidden" id="matrix-riddle"></p>
        <pre class="matrix-dialog__screen" aria-hidden="true"></pre>
        <form class="matrix-dialog__form" hidden>
          <label class="matrix-dialog__label" for="matrix-answer" data-i18n="matrix.inputLabel"></label>
          <div class="matrix-dialog__row">
            <span class="matrix-dialog__prompt" aria-hidden="true">&gt;</span>
            <input class="matrix-dialog__input" id="matrix-answer" name="answer" type="text"
              autocomplete="off" autocapitalize="off" spellcheck="false">
            <button class="matrix-dialog__submit" type="submit" data-i18n="matrix.submit"></button>
          </div>
        </form>
        <p class="matrix-dialog__feedback" role="status" aria-live="polite"></p>
        <button class="matrix-dialog__close" type="button" data-i18n-attr="aria-label:matrix.close">
          <span aria-hidden="true">&times;</span>
        </button>`;
      document.body.append(dialog);
      i18n.fill(dialog); // fill data-i18n strings of the new nodes

      const lines = ['matrix.line1', 'matrix.line2', 'matrix.line3'].map((key) => i18n.t(key));
      $('#matrix-riddle', dialog).textContent = lines.join(' ');

      const form = $('form', dialog);
      const input = $('input', dialog);
      const feedback = $('.matrix-dialog__feedback', dialog);
      const { signal } = session.controller;

      dialog.addEventListener(
        'cancel',
        (event) => {
          event.preventDefault();
          exit();
        },
        { signal },
      );
      $('.matrix-dialog__close', dialog).addEventListener('click', () => exit(), { signal });

      dialog.addEventListener(
        'keydown',
        (event) => {
          if (event.key !== 'Tab') return;
          const focusable = $$('button, input', dialog).filter((el) => !el.closest('[hidden]'));
          const first = focusable[0];
          const last = focusable.at(-1);
          if (event.shiftKey && document.activeElement === first) {
            event.preventDefault();
            last.focus();
          } else if (!event.shiftKey && document.activeElement === last) {
            event.preventDefault();
            first.focus();
          }
        },
        { signal },
      );

      form.addEventListener(
        'submit',
        (event) => {
          event.preventDefault();
          const answer = normalizeAnswer(input.value);
          feedback.classList.remove('is-correct', 'is-wrong');
          if (!answer) {
            feedback.textContent = i18n.t('matrix.empty');
            return;
          }
          const correct = MATRIX.answers.includes(answer);
          feedback.textContent = i18n.t(correct ? 'matrix.correct' : 'matrix.wrong');
          feedback.classList.add(correct ? 'is-correct' : 'is-wrong');
          if (correct) {
            input.readOnly = true;
            $('.matrix-dialog__close', dialog).focus();
          } else {
            input.select();
          }
        },
        { signal },
      );

      session.dialog = dialog;
      dialog.showModal();
      $('.matrix-dialog__close', dialog).focus();

      typeLines($('pre', dialog), lines, () => {
        form.hidden = false;
        input.focus();
      });
    };

    const enter = () => {
      session = { controller: new AbortController() };
      root.classList.add('matrix-mode');
      storage.secrets.add('matrix');
      if (reducedMotion.matches) {
        openDialog();
        return;
      }
      startRain(() => {
        session.stopRain();
        session.canvas.classList.add('is-fading');
        openDialog();
      });
    };

    const exit = () => {
      if (!session) return;
      session.stopRain?.();
      window.clearTimeout(session.typeTimer);
      session.controller.abort(); // removes every listener added for this session
      session.canvas?.remove();
      if (session.dialog?.open) session.dialog.close();
      session.dialog?.remove();
      session = null;
      root.classList.remove('matrix-mode');
      clickTimes = [];
      logo.focus();
    };

    logo.addEventListener('click', (event) => {
      const now = Date.now();
      clickTimes = clickTimes.filter((time) => now - time <= MATRIX.windowMs);
      clickTimes.push(now);

      if (clickTimes.length === MATRIX.hintAt && !session && !reducedMotion.matches) {
        logo.classList.remove('logo--glitch');
        void logo.offsetWidth; // restart the animation
        logo.classList.add('logo--glitch');
      }

      if (clickTimes.length >= MATRIX.clicks) {
        event.preventDefault(); // only the 7th click skips navigation
        clickTimes = [];
        if (session) exit();
        else enter();
      }
    });
    logo.addEventListener('animationend', () => logo.classList.remove('logo--glitch'));

    return {
      start: () => {
        if (!session) enter();
      },
    };
  };

  const matrix = initMatrixEgg();
  bus.on('matrix', () => matrix?.start());
})();

(() => {
  'use strict';

  const SECRETS = ['matrix', 'night404', 'terminal', 'archive'];
  const HOME = '/home/student';
  const LONG_PRESS_MS = 2000;
  const TYPE_CHARS_PER_FRAME = 6;
  const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');

  const { i18n, storage, bus } = window.CNTU;

  const file = (key) => ({ type: 'file', key });
  const dir = (children) => ({ type: 'dir', children });

  const FS = dir({
    home: dir({
      student: dir({
        'readme.txt': file('readme'),
        'schedule.txt': file('schedule'),
        '.bash_history': {
          type: 'file',
          text: 'ls -a\ncd .secrets\ncat hint1.txt\nsudo make me a sandwich',
        },
        lectures: dir({
          'algebra.txt': file('algebra'),
          'programming.txt': file('programming'),
        }),
        '.secrets': dir({
          'hint1.txt': file('hint1'),
          'hint2.txt': file('hint2'),
          'hint3.txt': file('hint3'),
          'archive.lnk': { type: 'link', target: 'archive' },
        }),
      }),
    }),
    'corpus-404': { type: 'locked' },
    etc: dir({ motd: { type: 'file', text: 'KNTU GNU/Linux 6.6.6-kntu' } }),
  });

  const $ = (selector, scope = document) => scope.querySelector(selector);
  const lang = () => i18n.supported(document.documentElement.lang) ?? i18n.defaultLang;
  const s = () => i18n.dicts[lang()]?.terminal ?? i18n.dicts[i18n.defaultLang]?.terminal;
  const jaOnly = () => (lang() === 'ja' ? (i18n.dicts.ja?.jaOnly ?? null) : null);
  const pick = (list) => list[Math.floor(Math.random() * list.length)];

  const readSecrets = storage.secrets.list;
  const markSecret = storage.secrets.add;

  const resolvePath = (cwd, input = '') => {
    let path = input.trim() || '~';
    if (path === '~' || path.startsWith('~/')) path = HOME + path.slice(1);
    const parts = (path.startsWith('/') ? path : `${cwd}/${path}`).split('/');
    const stack = [];
    parts.forEach((part) => {
      if (!part || part === '.') return;
      if (part === '..') stack.pop();
      else stack.push(part);
    });
    return `/${stack.join('/')}`;
  };

  const getNode = (path) =>
    path
      .split('/')
      .filter(Boolean)
      .reduce((node, name) => (node?.type === 'dir' ? node.children[name] : undefined), FS);

  const displayPath = (path) => (path.startsWith(HOME) ? `~${path.slice(HOME.length)}` : path);

  const siteUrl = (page) => {
    if (window.location.protocol === 'file:') return page === 'missing' ? '404.html' : page;
    const target = page === 'missing' ? 'corpus-404/' : page;
    return new URL(target, document.baseURI).href;
  };

  const PET_MESSAGE = 'Access granted. Cat privileges enabled.';

  const catPresent = () => {
    const detail = { present: false };
    bus.emit('cat-query', detail);
    return detail.present;
  };

  const COMMANDS = {
    help: {
      run: () => [
        s().help,
        ...Object.entries(s().descriptions).map(([name, desc]) => `  ${name.padEnd(9)} ${desc}`),
      ],
    },
    clear: { run: (_, sh) => sh.clear() },
    whoami: { run: () => (catPresent() ? [s().whoami, s().whoamiCat] : s().whoami) },
    date: {
      run: () =>
        new Date().toLocaleString(s().locale, {
          dateStyle: 'full',
          timeStyle: 'medium',
        }),
    },
    pwd: { run: (_, sh) => sh.cwd },
    uname: {
      run: (args) =>
        args.includes('-a')
          ? 'Linux kntu 6.6.6-kntu #1929 SMP PREEMPT_DYNAMIC Tue Oct 13 03:17:00 EEST 2026 x86_64 GNU/Linux'
          : 'Linux',
    },
    echo: { run: (args) => args.join(' ') },
    history: {
      run: (_, sh) =>
        sh.history.length
          ? sh.history.map((line, i) => `${String(i + 1).padStart(4)}  ${line}`)
          : s().history,
    },
    ls: {
      run: (args, sh) => {
        const showAll = args.some((arg) => /^-\w*a/.test(arg));
        const target = args.find((arg) => !arg.startsWith('-'));
        const path = resolvePath(sh.cwd, target ?? '.');
        const node = getNode(path);
        if (!node) return s().lsMissing(target);
        if (node.type !== 'dir') return target;
        const names = Object.keys(node.children)
          .filter((name) => showAll || !name.startsWith('.'))
          .map((name) => (node.children[name].type === 'dir' ? `${name}/` : name));
        return (showAll ? ['./', '../', ...names] : names).join('  ');
      },
    },
    cd: {
      run: (args, sh) => {
        const path = resolvePath(sh.cwd, args[0] ?? '~');
        const node = getNode(path);
        if (node?.type === 'locked') return s().cdLocked;
        if (!node) return s().cdMissing(args[0]);
        if (node.type !== 'dir') return s().cdNotDir(args[0]);
        sh.setCwd(path);
        return undefined;
      },
    },
    cat: {
      run: (args, sh) => {
        if (!args.length) return undefined;
        const node = getNode(resolvePath(sh.cwd, args[0]));
        if (!node || node.type === 'locked') return s().catMissing(args[0]);
        if (node.type === 'dir') return s().catDir(args[0]);
        if (node.type === 'link') return sh.navigate('archive');
        return (node.text ?? s().files[node.key]).split('\n');
      },
    },
    joke: { run: () => pick(s().jokes) },
    hint: {
      run: (_, sh) => {
        const hints = s().hints;
        const line = hints[sh.nextHint % hints.length];
        sh.nextHint += 1;
        return line;
      },
    },
    open: {
      args: () => ['404', 'archive'],
      run: (args, sh) => {
        const target = (args[0] ?? '').toLowerCase();
        if (target === '404') return sh.navigate('missing');
        if (target === 'archive') return sh.navigate('archive');
        return s().openUsage;
      },
    },
    goto: {
      run: (args, sh) => (args[0] === 'corpus' ? sh.navigate('missing') : s().openUsage),
    },
    matrix: {
      run: (_, sh) => {
        sh.close({ restoreFocus: false });
        bus.emit('matrix');
        return s().matrix;
      },
    },
    theme: {
      args: () => ['dark', 'light'],
      run: (args) => {
        if (args[0] !== 'dark' && args[0] !== 'light') return s().themeUsage;
        document.dispatchEvent(new CustomEvent('kntu:theme', { detail: { theme: args[0] } }));
        return s().themeSet(args[0]);
      },
    },
    lang: {
      args: () => i18n.langs,
      run: (args, sh) => {
        const code = i18n.supported(args[0]);
        if (!code) return s().langUsage;
        document.dispatchEvent(new CustomEvent('kntu:lang', { detail: { lang: code } }));
        i18n.load(code).then((dict) => sh.print(dict?.terminal.langSet ?? s().langUsage));
        return undefined;
      },
    },
    secrets: {
      run: () => {
        const found = readSecrets();
        const count = SECRETS.filter((id) => found.includes(id)).length;
        return [
          s().secretsTitle(count, SECRETS.length),
          ...SECRETS.map((id) => `  [${found.includes(id) ? 'x' : ' '}] ${s().secretNames[id]}`),
          ...(count === SECRETS.length ? ['', s().secretsAll] : []),
          ...(found.includes('records') && jaOnly() ? [`  [x] ${jaOnly().secretName}`] : []),
          ...(found.includes('agent') ? [`  [x] ${s().secretNames.agent}`] : []),
        ];
      },
    },
    hidden: { run: (args) => (args[0] === 'page' ? s().hiddenPage : s().notFound('hidden')) },
    sudo: { run: () => s().sudo },
    rm: {
      run: (args) =>
        args.some((arg) => /^-\w*r/.test(arg)) && args.includes('/') ? s().rmrf : s().rmUsage,
    },
    neo: { run: () => s().neo },
    red: { run: (args) => (args[0] === 'pill' ? s().neo : s().notFound('red')) },
    exit: { run: (_, sh) => sh.close() },
    開錠: {
      hidden: true,
      run: (args) => {
        const ja = jaOnly();
        if (!ja) return s().notFound('開錠');
        if (!args.length) return ja.usage;
        if (!ja.answers.includes(args.join(''))) return ja.wrong;
        if (readSecrets().includes('records')) return ja.already;
        markSecret('records');
        return ja.opened;
      },
    },
    pet: {
      hidden: true,
      run: () => {
        const detail = { present: false };
        bus.emit('cat-pet', detail);
        return detail.present ? PET_MESSAGE : [PET_MESSAGE, s().petNoCat];
      },
    },
  };
  COMMANDS.achievements = COMMANDS.secrets;

  const restore = (el) => {
    if (!el?.isConnected) return;
    el.focus();
    if (document.activeElement === el) return;
    const container = el.closest('[data-focus-fallback]');
    if (container) $(container.dataset.focusFallback)?.focus();
  };

  const createTerminal = () => {
    let dialog = null;
    let output = null;
    let input = null;
    let promptEl = null;
    let returnFocus = null;
    let typing = Promise.resolve();
    const state = { cwd: HOME, history: [], historyIndex: 0, nextHint: 0 };

    const promptText = () => `student@kntu:${displayPath(state.cwd)}$`;

    const print = (lines, className = '') => {
      const text = [].concat(lines).join('\n');
      const block = document.createElement('div');
      block.className = `terminal__block ${className}`.trim();
      const visual = document.createElement('span');
      visual.setAttribute('aria-hidden', 'true');
      const spoken = document.createElement('span');
      spoken.className = 'visually-hidden';
      spoken.textContent = text;
      block.append(visual, spoken);
      output.append(block);

      if (reducedMotion.matches || !text) {
        visual.textContent = text;
        output.scrollTop = output.scrollHeight;
        return;
      }
      typing = typing.then(
        () =>
          new Promise((resolve) => {
            let index = 0;
            const step = () => {
              if (!visual.isConnected) return resolve();
              index = Math.min(text.length, index + TYPE_CHARS_PER_FRAME);
              visual.textContent = text.slice(0, index);
              output.scrollTop = output.scrollHeight;
              if (index < text.length) window.requestAnimationFrame(step);
              else resolve();
            };
            step();
          }),
      );
    };

    const clear = () => {
      output.replaceChildren();
    };

    const renderChrome = () => {
      if (!dialog) return;
      $('.terminal__title', dialog).textContent = s().title;
      $('.terminal__label', dialog).textContent = s().inputLabel;
      $('.terminal__close', dialog).setAttribute('aria-label', s().close);
      dialog.lang = lang();
      promptEl.textContent = promptText();
    };

    const shell = {
      get cwd() {
        return state.cwd;
      },
      setCwd: (path) => {
        state.cwd = path;
        promptEl.textContent = promptText();
      },
      get history() {
        return state.history;
      },
      get nextHint() {
        return state.nextHint;
      },
      set nextHint(value) {
        state.nextHint = value;
      },
      clear,
      print: (lines) => print(lines),
      close: (options) => close(options),
      navigate: (page) => {
        const url = siteUrl(page === 'archive' ? 'secret.html' : 'missing');
        print(s().openingPage(page === 'archive' ? 'secret.html' : '404'));
        window.setTimeout(() => window.location.assign(url), reducedMotion.matches ? 0 : 400);
      },
    };

    const run = (line) => {
      print(`${promptText()} ${line}`, 'terminal__echo');
      const trimmed = line.trim();
      if (!trimmed) return;
      state.history.push(trimmed);
      state.historyIndex = state.history.length;

      if (/^rm\s+-\w*r\w*\s+\/\s*$/.test(trimmed) || trimmed === 'rm -rf /') {
        print(s().rmrf);
        return;
      }
      const [name, ...args] = trimmed.split(/\s+/);
      const command = COMMANDS[name.toLowerCase()];
      if (!command) {
        print([s().notFound(name), pick(s().notFoundHint)], 'terminal__error');
        return;
      }
      const result = command.run(args, shell);
      if (result !== undefined && dialog) print(result);
    };

    const complete = () => {
      const value = input.value;
      const parts = value.split(/\s+/);
      if (parts.length === 1) {
        const matches = Object.keys(COMMANDS).filter(
          (name) => !COMMANDS[name].hidden && name.startsWith(parts[0]),
        );
        if (matches.length === 1) input.value = `${matches[0]} `;
        else if (matches.length > 1) print(matches.join('  '));
        return;
      }
      const argsOf = COMMANDS[parts[0]]?.args;
      if (argsOf && parts.length === 2) {
        const matches = argsOf().filter((arg) => arg.startsWith(parts[1]));
        if (matches.length === 1) input.value = `${parts[0]} ${matches[0]}`;
        else if (matches.length > 1) print(matches.join('  '));
        return;
      }
      const partial = parts.at(-1);
      const slash = partial.lastIndexOf('/');
      const dirPart = slash >= 0 ? partial.slice(0, slash + 1) : '';
      const namePart = partial.slice(slash + 1);
      const node = getNode(resolvePath(state.cwd, dirPart || '.'));
      if (node?.type !== 'dir') return;
      const matches = Object.keys(node.children).filter((name) => name.startsWith(namePart));
      if (matches.length === 1) {
        const isDir = node.children[matches[0]].type === 'dir';
        parts[parts.length - 1] = `${dirPart}${matches[0]}${isDir ? '/' : ''}`;
        input.value = parts.join(' ');
      } else if (matches.length > 1) {
        print(matches.join('  '));
      }
    };

    const onKeydown = (event) => {
      if (event.key === 'Tab' && !event.shiftKey && event.target === input) {
        event.preventDefault();
        complete();
      } else if (event.key === 'Tab') {
        event.preventDefault();
        (event.target === input ? $('.terminal__close', dialog) : input).focus();
      } else if (event.target !== input) {
      } else if (event.key === 'Enter') {
        event.preventDefault();
        const line = input.value;
        input.value = '';
        run(line);
      } else if (event.key === 'ArrowUp' || event.key === 'ArrowDown') {
        event.preventDefault();
        const delta = event.key === 'ArrowUp' ? -1 : 1;
        state.historyIndex = Math.max(
          0,
          Math.min(state.history.length, state.historyIndex + delta),
        );
        input.value = state.history[state.historyIndex] ?? '';
      } else if (event.ctrlKey && event.key.toLowerCase() === 'l') {
        event.preventDefault();
        clear();
      } else if (
        event.ctrlKey &&
        event.key.toLowerCase() === 'c' &&
        input.selectionStart === input.selectionEnd // keep Ctrl+C = copy when text is selected
      ) {
        event.preventDefault();
        print(`${promptText()} ${input.value}^C`, 'terminal__echo');
        input.value = '';
      }
    };

    const build = () => {
      dialog = document.createElement('dialog');
      dialog.className = 'terminal';
      dialog.setAttribute('aria-modal', 'true');
      dialog.setAttribute('aria-labelledby', 'terminal-title');
      dialog.innerHTML = `
        <div class="terminal__bar">
          <span class="terminal__dots" aria-hidden="true"><i></i><i></i><i></i></span>
          <h2 class="terminal__title" id="terminal-title"></h2>
          <button class="terminal__close" type="button"><span aria-hidden="true">&times;</span></button>
        </div>
        <div class="terminal__output" role="log" aria-live="polite"></div>
        <form class="terminal__form" autocomplete="off">
          <label class="terminal__label visually-hidden" for="terminal-input"></label>
          <span class="terminal__prompt" aria-hidden="true"></span>
          <input class="terminal__input" id="terminal-input" type="text" autocapitalize="off"
            autocomplete="off" spellcheck="false" enterkeyhint="send">
        </form>`;
      document.body.append(dialog);
      output = $('.terminal__output', dialog);
      input = $('.terminal__input', dialog);
      promptEl = $('.terminal__prompt', dialog);

      dialog.addEventListener('keydown', onKeydown);
      $('form', dialog).addEventListener('submit', (event) => event.preventDefault());
      dialog.addEventListener('cancel', (event) => {
        event.preventDefault();
        close();
      });
      $('.terminal__close', dialog).addEventListener('click', () => close());
      output.addEventListener('click', () => input.focus());
    };

    const open = () => {
      if (dialog?.open) return;
      if (!s()) {
        i18n.load(lang()).then((dict) => dict && open()); // dictionary still loading
        return;
      }
      returnFocus = document.activeElement;
      if (!dialog) build();
      renderChrome();
      promptEl.textContent = promptText();
      dialog.showModal();
      document.documentElement.classList.add('terminal-open');
      input.focus();
      if (!output.childElementCount) print(s().motd, 'terminal__motd');
      markSecret('terminal');
    };

    function close({ restoreFocus = true } = {}) {
      if (!dialog?.open) return;
      input.blur(); // otherwise the hidden input keeps focus and eats the next key
      dialog.close();
      document.documentElement.classList.remove('terminal-open');
      if (restoreFocus) restore(returnFocus);
    }

    const toggle = () => (dialog?.open ? close() : open());

    bus.on('lang-changed', renderChrome);
    bus.on('cat-again', (event) => {
      if (!dialog?.open) return;
      event.detail.handled = true;
      input.value = '';
      print(`$ ${event.detail.text}`, 'terminal__echo');
    });

    return { open, close, toggle, isOpen: () => Boolean(dialog?.open) };
  };

  const isTypingTarget = (el) =>
    el instanceof HTMLElement &&
    (el.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(el.tagName));

  const initTriggers = (terminal) => {
    let typed = '';

    document.addEventListener('keydown', (event) => {
      const busy =
        document.documentElement.classList.contains('matrix-mode') ||
        [...document.querySelectorAll('dialog[open]')].some(
          (d) => !d.classList.contains('terminal'),
        );
      if (event.ctrlKey && event.shiftKey && event.code === 'KeyU') {
        event.preventDefault();
        if (!busy) terminal.toggle();
        return;
      }
      if (terminal.isOpen() || isTypingTarget(event.target) || busy) return;
      if (event.ctrlKey || event.altKey || event.metaKey) return;

      if (event.key === '`') {
        event.preventDefault();
        terminal.open();
        return;
      }
      if (event.key.length === 1) {
        typed = (typed + event.key.toLowerCase()).slice(-4);
        if (typed === 'sudo') {
          typed = '';
          event.preventDefault(); // keep the final "o" out of the input
          terminal.open();
        }
      }
    });

    const target = $('.footer__bottom p');
    if (!target) return;
    let timer = 0;
    const cancel = () => window.clearTimeout(timer);
    target.addEventListener('pointerdown', () => {
      cancel();
      timer = window.setTimeout(() => {
        if (!document.documentElement.classList.contains('matrix-mode')) terminal.open();
      }, LONG_PRESS_MS);
    });
    ['pointerup', 'pointerleave', 'pointercancel', 'pointermove'].forEach((type) =>
      target.addEventListener(type, (event) => {
        if (type !== 'pointermove' || Math.abs(event.movementX) + Math.abs(event.movementY) > 6) {
          cancel();
        }
      }),
    );
    target.addEventListener('contextmenu', (event) => {
      if (timer) event.preventDefault();
    });
  };

  initTriggers(createTerminal());
})();

(() => {
  'use strict';

  const KEY_SEQUENCE = [
    'ArrowUp',
    'ArrowUp',
    'ArrowDown',
    'ArrowDown',
    'ArrowLeft',
    'ArrowRight',
    'ArrowLeft',
    'ArrowRight',
    'KeyB',
    'KeyA',
  ];
  const TOUCH_SEQUENCE = [
    'up',
    'up',
    'down',
    'down',
    'left',
    'right',
    'left',
    'right',
    'tap',
    'tap',
  ];
  const SWIPE_MIN_PX = 30;
  const TAP_MAX_PX = 10;
  const FLASH_MS = 300;
  const SIT_DELAY_MS = 900;
  const BUBBLE_MS = 3500;
  const MESSAGE = 'Meow.exe executed successfully.';
  const AGAIN = 'You again?';
  const SERIOUSLY = 'Seriously?';
  const IDLE_MIN_MS = 6000;
  const IDLE_MAX_MS = 15000;
  const SUSPICIOUS_MS = 3500;

  const { i18n, bus } = window.CNTU;
  const FALLBACK = { label: 'Pixel black cat', said: MESSAGE, again: AGAIN, seriously: SERIOUSLY };
  const str = (key) =>
    (i18n.dicts[document.documentElement.lang] ?? i18n.dicts.uk)?.cat?.[key] ?? FALLBACK[key];

  const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');

  const isBlocked = (target) =>
    (target instanceof HTMLElement &&
      (target.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(target.tagName))) ||
    Boolean(document.querySelector('dialog[open]')) || // terminal or Matrix
    document.documentElement.classList.contains('matrix-mode');

  const r = (x, y, w, h, cls = '') =>
    `<rect x="${x}" y="${y}" width="${w}" height="${h}"${cls ? ` class="${cls}"` : ''}/>`;

  const CAT_SVG = `
<svg class="konami-cat__svg" viewBox="0 0 16 16" width="64" height="64" shape-rendering="crispEdges" aria-hidden="true" focusable="false">
  <g class="konami-cat__fur">
    ${r(3, 1, 2, 2)}${r(11, 1, 2, 2)}${r(2, 3, 12, 7)}
    <g class="konami-cat__pose konami-cat__pose--stand">
      ${r(1, 10, 14, 3)}${r(2, 13, 2, 3)}${r(6, 13, 1, 3)}${r(10, 13, 1, 3)}${r(12, 13, 2, 3)}${r(15, 6, 1, 5)}
    </g>
    <g class="konami-cat__pose konami-cat__pose--sit">
      ${r(3, 10, 10, 5)}${r(4, 15, 2, 1)}${r(10, 15, 2, 1)}
      <g class="konami-cat__tail">${r(13, 13, 2, 2)}${r(14, 10, 2, 3)}</g>
    </g>
  </g>
  ${r(7, 8, 2, 1, 'konami-cat__nose')}
  <g class="konami-cat__eyes">
    ${r(4, 5, 3, 2, 'konami-cat__eye')}${r(9, 5, 3, 2, 'konami-cat__eye')}
    ${r(5, 5, 1, 1, 'konami-cat__pupil')}${r(10, 5, 1, 1, 'konami-cat__pupil')}
  </g>
  <g class="konami-cat__sus">
    ${r(4, 6, 3, 1, 'konami-cat__eye')}${r(9, 6, 3, 1, 'konami-cat__eye')}
    ${r(6, 6, 1, 1, 'konami-cat__slit')}${r(9, 6, 1, 1, 'konami-cat__slit')}
    ${r(4, 4, 3, 1, 'konami-cat__brow')}${r(9, 4, 3, 1, 'konami-cat__brow')}
    ${r(13, 0, 3, 1, 'konami-cat__mark')}${r(15, 1, 1, 1, 'konami-cat__mark')}${r(14, 2, 1, 1, 'konami-cat__mark')}${r(14, 4, 1, 1, 'konami-cat__mark')}
  </g>
  <g class="konami-cat__deadpan">
    ${r(4, 6, 3, 1, 'konami-cat__eye')}${r(9, 6, 3, 1, 'konami-cat__eye')}
    ${r(5, 6, 1, 1, 'konami-cat__slit')}${r(10, 6, 1, 1, 'konami-cat__slit')}
    ${r(4, 5, 3, 1, 'konami-cat__brow')}${r(9, 5, 3, 1, 'konami-cat__brow')}
    ${r(14, 2, 1, 1, 'konami-cat__sweat')}${r(13, 3, 2, 2, 'konami-cat__sweat')}
  </g>
  <g class="konami-cat__lids">${r(4, 6, 3, 1, 'konami-cat__eye')}${r(9, 6, 3, 1, 'konami-cat__eye')}</g>
</svg>`;

  const flash = () => {
    const el = document.createElement('div');
    el.className = 'konami-flash';
    el.setAttribute('aria-hidden', 'true');
    document.body.append(el);
    window.setTimeout(() => el.remove(), FLASH_MS);
  };

  let cat = null; // { again, pet } while the cat exists

  const createCat = () => {
    const wrap = document.createElement('div');
    wrap.className = 'konami-cat';
    wrap.innerHTML = `
      <p class="konami-cat__bubble" role="status" aria-live="polite">
        <span class="konami-cat__bubble-text" aria-hidden="true"></span>
        <span class="konami-cat__bubble-sr visually-hidden"></span>
      </p>
      <button class="konami-cat__button" type="button">${CAT_SVG}</button>`;
    document.body.append(wrap);

    const button = wrap.querySelector('.konami-cat__button');
    const bubble = wrap.querySelector('.konami-cat__bubble');
    const pupils = [...wrap.querySelectorAll('.konami-cat__pupil')];
    const label = () => button.setAttribute('aria-label', str('label'));
    label();
    bus.on('lang-changed', label);

    let pointer = null;
    let frame = 0;
    const look = () => {
      frame = 0;
      if (!pointer) return;
      const box = button.getBoundingClientRect();
      const ex = box.left + box.width / 2;
      const ey = box.top + box.height * 0.36;
      const dx = Math.abs(pointer.x - ex) < 12 ? 0 : Math.sign(pointer.x - ex);
      const dy = pointer.y > ey + 12 ? 1 : 0;
      pupils.forEach((p, i) => {
        p.setAttribute('x', String((i ? 10 : 5) + dx));
        p.setAttribute('y', String(5 + dy));
      });
    };
    const track = (event) => {
      const point = event.touches ? event.touches[0] : event;
      if (!point) return;
      pointer = { x: point.clientX, y: point.clientY };
      if (!frame) frame = window.requestAnimationFrame(look);
    };
    window.addEventListener('pointermove', track, { passive: true });
    window.addEventListener('touchstart', track, { passive: true });

    const flashClass = (cls, ms) => {
      wrap.classList.add(cls);
      window.setTimeout(() => wrap.classList.remove(cls), ms);
    };
    const blink = () => flashClass('is-blinking', 160);
    const swish = () => flashClass('is-swishing', 700);

    let idleTimer = 0;
    const scheduleIdle = () => {
      window.clearTimeout(idleTimer);
      if (document.hidden || reducedMotion.matches) return;
      idleTimer = window.setTimeout(
        () => {
          if (Math.random() < 0.5) blink();
          else swish();
          scheduleIdle();
        },
        IDLE_MIN_MS + Math.random() * (IDLE_MAX_MS - IDLE_MIN_MS),
      );
    };
    scheduleIdle();
    document.addEventListener('visibilitychange', scheduleIdle);
    reducedMotion.addEventListener('change', scheduleIdle);

    window.setTimeout(() => wrap.classList.add('is-sitting'), SIT_DELAY_MS);

    let bubbleTimer = 0;
    const say = (text, srText, terminalStyle = false) => {
      bubble.querySelector('.konami-cat__bubble-text').textContent = text;
      bubble.querySelector('.konami-cat__bubble-sr').textContent = srText;
      bubble.setAttribute('aria-label', srText);
      wrap.classList.toggle('is-terminal', terminalStyle);
      wrap.classList.add('has-bubble');
      window.clearTimeout(bubbleTimer);
      bubbleTimer = window.setTimeout(() => wrap.classList.remove('has-bubble'), BUBBLE_MS);
    };

    button.addEventListener('click', () => {
      say(MESSAGE, str('said'));
      flashClass('is-purring', 600);
      blink();
    });

    let entries = 1;
    let faceTimer = 0;
    const again = () => {
      entries += 1;
      const fed = entries >= 3;
      const text = fed ? SERIOUSLY : AGAIN;
      wrap.classList.remove('is-suspicious', 'is-deadpan');
      wrap.classList.add(fed ? 'is-deadpan' : 'is-suspicious');
      window.clearTimeout(faceTimer);
      faceTimer = window.setTimeout(
        () => wrap.classList.remove('is-suspicious', 'is-deadpan'),
        SUSPICIOUS_MS,
      );
      const detail = { text, handled: false };
      bus.emit('cat-again', detail);
      if (!detail.handled) say(`$ ${text}`, str(fed ? 'seriously' : 'again'), true);
    };

    const pet = () => {
      flashClass('is-happy', 1200);
      swish();
    };

    requestAnimationFrame(() => wrap.classList.add('is-in'));
    return { again, pet };
  };

  const activate = () => {
    flash(); // CSS turns it into a subtle static tint under reduced motion
    if (cat) cat.again();
    else cat = createCat();
  };

  bus.on('cat-query', (event) => {
    event.detail.present = Boolean(cat);
  });
  bus.on('cat-pet', (event) => {
    event.detail.present = Boolean(cat);
    cat?.pet();
  });

  const makeMatcher = (sequence) => {
    let pos = 0;
    return (token) => {
      if (token === sequence[pos]) pos += 1;
      else pos = token === sequence[0] ? 1 : 0;
      if (pos === sequence.length) {
        pos = 0;
        activate();
        return true;
      }
      return false;
    };
  };

  const keyMatch = makeMatcher(KEY_SEQUENCE);
  document.addEventListener('keydown', (event) => {
    if (event.repeat || event.ctrlKey || event.altKey || event.metaKey) return;
    const inTerminal = event.target instanceof HTMLElement && event.target.id === 'terminal-input';
    if (!(cat && inTerminal) && isBlocked(event.target)) return;
    if (event.target instanceof Element && event.target.closest('[role="menu"]')) return;
    if (keyMatch(event.code) && inTerminal) event.preventDefault();
  });

  const touchMatch = makeMatcher(TOUCH_SEQUENCE);
  let start = null;
  document.addEventListener(
    'touchstart',
    (event) => {
      start =
        event.touches.length === 1
          ? { x: event.touches[0].clientX, y: event.touches[0].clientY }
          : null;
    },
    { passive: true },
  );
  document.addEventListener(
    'touchend',
    (event) => {
      if (!start || isBlocked(event.target)) return;
      const t = event.changedTouches[0];
      const dx = t.clientX - start.x;
      const dy = t.clientY - start.y;
      start = null;
      const dist = Math.max(Math.abs(dx), Math.abs(dy));
      if (dist <= TAP_MAX_PX) touchMatch('tap');
      else if (dist >= SWIPE_MIN_PX) {
        if (Math.abs(dx) > Math.abs(dy)) touchMatch(dx > 0 ? 'right' : 'left');
        else touchMatch(dy > 0 ? 'down' : 'up');
      }
    },
    { passive: true },
  );
})();
